package com.example.ancapp.data

import androidx.room.Entity
import androidx.room.ForeignKey
import androidx.room.Index
import androidx.room.PrimaryKey
import androidx.room.TypeConverter
import java.time.LocalDate
import java.time.Period
import java.time.temporal.ChronoUnit

@Entity(tableName = "patients")
data class Patient(
  @PrimaryKey(autoGenerate = true) val id: Long = 0,
  val name: String,
  val dateOfBirth: LocalDate,
  val dueDate: LocalDate,
) {
  fun ageYears(today: LocalDate = LocalDate.now()): Int =
    Period.between(dateOfBirth, today).years

  // Full pregnancy is 280 days; gestational age counts back from the due date.
  fun gestationalWeeks(today: LocalDate = LocalDate.now()): Int =
    ((280 - ChronoUnit.DAYS.between(today, dueDate)) / 7).toInt().coerceAtLeast(0)
}

enum class DangerSign(val label: String) {
  VAGINAL_BLEEDING("Vaginal bleeding"),
  SEVERE_HEADACHE("Severe headache"),
  BLURRED_VISION("Blurred vision"),
  FEVER("Fever"),
}

@Entity(
  tableName = "visits",
  foreignKeys = [
    ForeignKey(
      entity = Patient::class,
      parentColumns = ["id"],
      childColumns = ["patientId"],
      onDelete = ForeignKey.CASCADE,
    )
  ],
  indices = [Index("patientId")],
)
data class Visit(
  @PrimaryKey(autoGenerate = true) val id: Long = 0,
  val patientId: Long,
  val date: LocalDate,
  val gestationalWeeks: Int,
  val weightKg: Double,
  val systolic: Int,
  val diastolic: Int,
  val hemoglobin: Double?,
  val dangerSigns: Set<DangerSign>,
  val notes: String,
)

class Converters {
  @TypeConverter
  fun localDateToString(value: LocalDate?): String? = value?.toString()

  @TypeConverter
  fun stringToLocalDate(value: String?): LocalDate? = value?.let(LocalDate::parse)

  @TypeConverter
  fun dangerSignsToString(value: Set<DangerSign>): String =
    value.joinToString(",") { it.name }

  @TypeConverter
  fun stringToDangerSigns(value: String): Set<DangerSign> =
    if (value.isEmpty()) emptySet()
    else value.split(",").map(DangerSign::valueOf).toSet()
}

