import androidx.compose.ui.unit.dp
import com.example.ancapp.AncViewModel
import com.example.ancapp.data.Patient
import java.time.format.DateTimeFormatter

val dateFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("d MMM yyyy")

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RegisterScreen(viewModel: AncViewModel, onPatientClick: (Long) -> Unit) {
  val patients by androidx.compose.runtime.remember { viewModel.patients }
    .collectAsState(initial = emptyList())

  Scaffold(topBar = { TopAppBar(title = { Text("ANC Register") }) }) { padding ->
    LazyColumn(
      modifier = Modifier.fillMaxSize().padding(padding),
      contentPadding = PaddingValues(16.dp),
      verticalArrangement = Arrangement.spacedBy(12.dp),
    ) {
      items(patients, key = { it.id }) { patient ->
        PatientCard(patient, onClick = { onPatientClick(patient.id) })
      }
    }
  }
}

@Composable
private fun PatientCard(patient: Patient, onClick: () -> Unit) {
  Card(onClick = onClick, modifier = Modifier.fillMaxWidth()) {
    Column(Modifier.padding(16.dp)) {
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically,
      ) {
        Text(patient.name, style = MaterialTheme.typography.titleMedium)
        Text(
          "${patient.gestationalWeeks()} wks",
          style = MaterialTheme.typography.titleMedium,
          color = MaterialTheme.colorScheme.primary,
        )
      }
      Text(
        "Age ${patient.ageYears()} · Due ${patient.dueDate.format(dateFormat)}",
        style = MaterialTheme.typography.bodyMedium,
        color = MaterialTheme.colorScheme.onSurfaceVariant,
      )
    }
  }
}

